function validateEvent(e) {
  if (!e) return false;
  const fields = ['user_id','event_type','ts','event_id'];
  for (const f of fields) if (!(f in e)) return false;
  const ts = Number(new Date(e.ts));
  if (Number.isNaN(ts) || ts < 0) return false;
